import csv
import io
import json
import os
import sys
from datetime import datetime, timedelta, timezone


def read_exports(directory):
    rows = []
    names = sorted(
        name for name in os.listdir(directory)
        if name.endswith(".csv") and os.path.isfile(os.path.join(directory, name))
    )
    for name in names:
        with open(os.path.join(directory, name), "rb") as handle:
            text = handle.read().decode("utf-8-sig")
        first = text.split("\n", 1)[0].rstrip("\r")
        delimiter = ","
        for candidate in (",", ";", "\t"):
            if candidate in first:
                delimiter = candidate
                break
        reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)
        header = None
        for cells in reader:
            if header is None:
                if not cells:
                    continue
                header = [cell.strip() for cell in cells]
                continue
            cells = [cell.strip() for cell in cells]
            if not any(cells):
                continue
            row = {}
            for index, column in enumerate(header):
                value = cells[index] if index < len(cells) else ""
                row[column] = value if value != "" else None
            rows.append(row)
    return rows


def parse_offset(text):
    sign = -1 if text[0] == "-" else 1
    hours, minutes = text[1:].split(":")
    return timezone(sign * timedelta(hours=int(hours), minutes=int(minutes)))


def parse_time(value, meta):
    if meta.get("submitted_format") == "local":
        moment = datetime.strptime(value, "%Y-%m-%d %H:%M:%S")
        return moment.replace(tzinfo=parse_offset(meta["utc_offset"]))
    if value.endswith("Z"):
        return datetime.fromisoformat(value[:-1]).replace(tzinfo=timezone.utc)
    date_part, time_part = value.split("T")
    for index, char in enumerate(time_part):
        if char in "+-":
            moment = datetime.strptime(date_part + "T" + time_part[:index], "%Y-%m-%dT%H:%M:%S")
            return moment.replace(tzinfo=parse_offset(time_part[index:]))
    return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S").replace(tzinfo=timezone.utc)


def parse_duration(value, meta):
    if meta.get("duration_format") == "clock":
        total = 0
        for part in value.split(":"):
            total = total * 60 + int(part)
        return total
    return int(value)


def to_code(value, recode):
    if recode is not None:
        return recode[value]
    return int(value)


def read_answer(question, entry, row, codebook):
    qtype = question["type"]
    if qtype == "single":
        value = row.get(entry["column"])
        if value is None:
            return None
        return to_code(value, entry.get("recode"))
    if qtype == "multi":
        recode = entry.get("recode")
        chosen = []
        if "columns" in entry:
            for code, column in entry["columns"].items():
                if row.get(column) == "1":
                    chosen.append(int(code))
        else:
            value = row.get(entry["column"])
            if value is not None:
                for element in value.split(entry["separator"]):
                    element = element.strip()
                    if element:
                        chosen.append(to_code(element, recode))
        chosen = set(chosen)
        if not chosen:
            return None
        exclusive = {o["code"] for o in question["options"] if o.get("exclusive")}
        others = chosen - exclusive
        if others:
            chosen = others
        elif len(chosen) >= 2:
            return None
        missing = {o["code"] for o in question["options"] if o.get("missing")}
        chosen -= missing
        return chosen or None
    value = row.get(entry["column"])
    if value is None:
        return None
    source = entry.get("source")
    if source == "band":
        return to_code(value, entry.get("recode"))
    age = int(value)
    if source == "birth_year":
        age = int(codebook["reference_date"][:4]) - age
    for band in question["bands"]:
        if band["min"] <= age <= band["max"]:
            return band["code"]
    return None


def median2(values):
    values = sorted(values)
    count = len(values)
    if count % 2:
        return values[count // 2] * 2
    return values[count // 2 - 1] + values[count // 2]


def main(input_dir, output_file):
    def load(name):
        with open(os.path.join(input_dir, name), encoding="utf-8") as handle:
            return json.load(handle)

    codebook = load("codebook.json")
    weighting = load("weighting.json")
    plan = load("tables.json")
    versions = codebook["versions"]
    questions = codebook["questions"]
    by_id = {q["id"]: q for q in questions}
    stats = {key: dict(rows=0, duplicates=0, short_partials=0, speeders=0, complete=0, partial=0)
             for key in versions}

    parsed = []
    for row in read_exports(os.path.join(input_dir, "exports")):
        key = row["form_version"]
        meta = versions[key]["meta"]
        complete = row.get(meta["status"]) == meta["complete"]
        record = {
            "row": row, "version": key, "meta": meta, "complete": complete,
            "id": row.get(meta["id"]),
            "time": parse_time(row[meta["submitted"]], meta),
        }
        stats[key]["rows"] += 1
        parsed.append(record)

    best = {}
    for record in parsed:
        current = best.get(record["id"])
        if current is None:
            best[record["id"]] = record
            continue
        if (record["complete"], record["time"]) > (current["complete"], current["time"]):
            loser, best[record["id"]] = current, record
        else:
            loser = record
        stats[loser["version"]]["duplicates"] += 1

    kept = []
    for record in parsed:
        if best[record["id"]] is not record:
            continue
        if not record["complete"]:
            record["last_page"] = int(record["row"][record["meta"]["last_page"]])
            if record["last_page"] < codebook["partial_min_page"]:
                stats[record["version"]]["short_partials"] += 1
                continue
        kept.append(record)

    durations = {}
    for record in kept:
        if record["complete"]:
            record["duration"] = parse_duration(record["row"][record["meta"]["duration"]], record["meta"])
            durations.setdefault(record["version"], []).append(record["duration"])
    medians = {key: median2(vals) for key, vals in durations.items()}
    final = []
    for record in kept:
        if record["complete"] and record["duration"] * 5 < medians[record["version"]]:
            stats[record["version"]]["speeders"] += 1
            continue
        final.append(record)
    for record in final:
        stats[record["version"]]["complete" if record["complete"] else "partial"] += 1

    for record in final:
        answers = {}
        for question in questions:
            entry = question["versions"].get(record["version"])
            if entry is None:
                continue
            if not record["complete"] and entry["page"] > record["last_page"]:
                continue
            ask_if = question.get("ask_if")
            if ask_if:
                earlier = answers.get(ask_if["question"])
                if earlier is None:
                    continue
                codes = set(ask_if["codes"])
                held = earlier in codes if not isinstance(earlier, set) else bool(earlier & codes)
                if not held:
                    continue
            answer = read_answer(question, entry, record["row"], codebook)
            if answer is None:
                continue
            if question["type"] != "multi":
                option_missing = {o["code"] for o in question.get("options", []) if o.get("missing")}
                if answer in option_missing:
                    continue
            answers[question["id"]] = answer
            record.setdefault("asked", set()).add(question["id"])
        record["answers"] = answers

    count = len(final)
    weights = [1.0] * count

    def category(record, dimension_question, targets):
        answer = record["answers"].get(dimension_question)
        if answer is not None and str(answer) in targets:
            return str(answer)
        return None

    dimensions = []
    for dimension in weighting["dimensions"]:
        question = dimension["question"]
        present = {str(r["answers"][question]) for r in final if question in r["answers"]}
        targets = {c: v for c, v in dimension["targets"].items() if c in present}
        total = sum(targets.values())
        if not targets or not total:
            continue
        shares = {c: v / total for c, v in targets.items()}
        cats = [category(r, question, shares) for r in final]
        dimensions.append((shares, cats))

    if count:
        for _ in range(weighting["max_iterations"]):
            settled = True
            for shares, cats in dimensions:
                sums = {}
                for weight, cat in zip(weights, cats):
                    if cat is not None:
                        sums[cat] = sums.get(cat, 0.0) + weight
                total = sum(sums.values())
                factors = {c: shares[c] * total / sums[c] for c in sums}
                for code, factor in factors.items():
                    if abs(factor - 1) > weighting["tolerance"]:
                        settled = False
                weights = [w * factors[c] if c is not None else w for w, c in zip(weights, cats)]
            if settled:
                break
        mean = sum(weights) / count
        high = weighting["cap"] * mean
        low = weighting["floor"] * mean
        weights = [min(max(w, low), high) for w in weights]
        scale = count / sum(weights)
        weights = [w * scale for w in weights]

    summary = {
        "versions": [dict(version=key, **stats[key]) for key in versions],
        "respondents": count,
        "effective_n": None, "weight_min": None, "weight_max": None,
    }
    if count:
        summary["effective_n"] = round(sum(weights) ** 2 / sum(w * w for w in weights), 2)
        summary["weight_min"] = round(min(weights), 2)
        summary["weight_max"] = round(max(weights), 2)

    def options_of(question):
        if question["type"] == "age":
            return [b["code"] for b in question["bands"]]
        return [o["code"] for o in question["options"] if not o.get("missing")]

    columns = [("total", None, None)]
    for banner in plan["banner"]:
        for code in options_of(by_id[banner]):
            columns.append((banner + ":" + str(code), banner, code))

    def contains(answer, codes):
        if isinstance(answer, set):
            return bool(answer & set(codes))
        return answer in codes

    tables = []
    for table in plan["tables"]:
        question = by_id[table["question"]]
        qid = question["id"]
        scores = {o["code"]: o.get("score") for o in question.get("options", [])}
        out_columns = []
        for name, banner, code in columns:
            members = [
                i for i, r in enumerate(final)
                if qid in r["answers"]
                and (banner is None or r["answers"].get(banner) == code)
            ]
            base = len(members)
            wbase = sum(weights[i] for i in members)
            rows = [(str(c), [c]) for c in options_of(question)]
            rows += [(net["id"], net["codes"]) for net in table.get("nets", [])]
            values = {}
            for key, codes in rows:
                if base == 0:
                    values[key] = None
                else:
                    part = sum(weights[i] for i in members if contains(final[i]["answers"][qid], codes))
                    values[key] = round(100 * part / wbase, 2)
            if table.get("mean"):
                if base == 0:
                    values["mean"] = None
                else:
                    total = sum(weights[i] * scores[final[i]["answers"][qid]] for i in members)
                    values["mean"] = round(total / wbase, 2)
            out_columns.append({
                "column": name, "base": base,
                "weighted_base": round(wbase, 2) if base else 0,
                "values": values,
            })
        tables.append({"table": table["id"], "columns": out_columns})

    result = {"survey": codebook["survey"], "summary": summary, "tables": tables}
    with open(output_file, "w", encoding="utf-8") as handle:
        json.dump(result, handle, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
